{
  "task": "PBR_material_extraction",
  "version": "1.0",
  "instructions": {
    "objective": "Analyze the provided 3D render and extract the minimum clean set of physically distinct materials required to recreate the asset in a game-ready PBR workflow.",
    "rules": [
      "Ignore lighting, baked shadows, specular highlights, and camera-induced color shifts — evaluate only intrinsic surface properties.",
      "Separate materials ONLY when they differ in material class, finish, coating, wear state, or surface treatment.",
      "Engravings, embossing, and relief carving on the same substrate are NOT separate materials — encode them as normal/height map detail on the parent material.",
      "Minimize material count. Merge materials that share identical PBR parameters.",
      "Output must be strict valid JSON only — no markdown, no prose outside the JSON block."
    ]
  },
  "output_schema": {
    "asset_summary": "string — one sentence describing the overall asset type and dominant material family",
    "material_count": "integer — total number of distinct materials identified",
    "materials": [
      {
        "id": "string — unique slug e.g. mat_01",
        "name": "string — human-readable material name",
        "material_class": "string — e.g. Metal, Fabric, Leather, Wood, Ceramic, Rubber, Organic",
        "coverage_region": "string — spatial description of where this material appears on the asset",
        "physical_description": "string — plain-language description of how this surface looks and behaves physically",
        "base_color_albedo": {
          "description": "string",
          "hex_approximation": "string — e.g. #8A8A8A",
          "value_range": "string — e.g. 0.35-0.45 linear"
        },
        "metallic": {
          "value": "float 0.0-1.0",
          "notes": "string"
        },
        "roughness": {
          "value_or_range": "float or range e.g. 0.2-0.45",
          "variation_map_needed": "boolean",
          "notes": "string"
        },
        "normal_micro_surface": {
          "description": "string — describe the normal map content needed",
          "intensity": "string — subtle / moderate / strong",
          "features": ["string — list of micro-surface features to bake or paint"]
        },
        "height_embossing": {
          "required": "boolean",
          "description": "string — describe displacement or parallax content if needed"
        },
        "surface_finish_treatment": "string — e.g. hand-polished, blued, niello-inlaid, acid-etched, burnished",
        "wear_aging_story": "string — describe oxidation, scratches, edge-wear, patina, grime accumulation",
        "reason_for_separation": "string — explicit physical justification for why this is its own material"
      }
    ]
  },
  "extracted_materials": {
    "asset_summary": "Elaborately engraved and embossed steel plate armour featuring high-relief floral and scrollwork decoration across breastplate, pauldrons, and tassets, with a secondary wrapped grip element.",
    "material_count": 3,
    "materials": [
      {
        "id": "mat_01",
        "name": "Polished Engraved Steel — Bright Plate",
        "material_class": "Metal",
        "coverage_region": "Primary armour plates: breastplate raised border zones, pauldron outer faces, tasset panels — all smooth planar and convex surfaces between engraved fields",
        "physical_description": "High-carbon steel plate that has been hand-polished to a near-mirror finish. Surfaces are specularly bright with gentle macro-form curvature. No coating. The steel has taken on a very faint warm silver tone consistent with polished iron alloy.",
        "base_color_albedo": {
          "description": "Neutral cool silver, very slightly warm in mid-tones",
          "hex_approximation": "#B0B0B2",
          "value_range": "0.42-0.55 linear"
        },
        "metallic": {
          "value": 1.0,
          "notes": "Full metallic. No dielectric coating. IOR-driven reflectance consistent with polished steel (F0 ~0.56)."
        },
        "roughness": {
          "value_or_range": "0.05-0.15",
          "variation_map_needed": true,
          "notes": "Lowest roughness on open planar faces; slightly higher in concave junctions and around rivet areas due to tooling contact."
        },
        "normal_micro_surface": {
          "description": "Very fine parallel polishing micro-scratches following the curvature of the form. Occasional shallow pit from period forging. No macro relief — all relief is handled by geometry or mat_02.",
          "intensity": "subtle",
          "features": [
            "Directional polishing scratch micro-detail",
            "Micro-pit clusters from hammer forging",
            "Edge chamfer normal transitions"
          ]
        },
        "height_embossing": {
          "required": false,
          "description": "Not required on this material zone; macro relief belongs to the engraved field material."
        },
        "surface_finish_treatment": "Hand-polished bright steel, no bluing or coating, wheel-finished then hand-burnished on high points",
        "wear_aging_story": "Minimal wear — ceremonial or display armour quality. Light micro-scratching on high contact points (shoulder rolls, chest centerline). No rust or oxidation visible. Very faint grime accumulation only in deepest recesses.",
        "reason_for_separation": "This zone has the lowest roughness value on the asset and carries no surface relief detail. It is the reference bright-polish state of the steel substrate and must remain isolated so the roughness gradient across the engraved fields can be authored relative to it."
      },
      {
        "id": "mat_02",
        "name": "Engraved and Embossed Steel — Relief Field",
        "material_class": "Metal",
        "coverage_region": "All engraved and embossed decorative panels: central breastplate rose and acanthus field, pauldron scrollwork panels, tasset border friezes, and all incised line-work channels across the armour surface",
        "physical_description": "Same steel alloy as mat_01 but the surface has been worked by engraving tools and repoussé hammering. The relief creates deep shadow-catching recesses alongside polished raised crests. Engraved channels are slightly darker due to micro-roughness from cutting tool marks and possible residual darkening agent (traditional blackening with oil or wax soot). High points of roses and acanthus leaves retain the bright polish of mat_01 character but transitions rapidly into matte in the cut valleys.",
        "base_color_albedo": {
          "description": "Same neutral steel silver as mat_01 on raised crests; transitions to a darker near-black in engraved grooves via roughness-driven darkening and possible thin oxidation layer",
          "hex_approximation": "#7A7A7C",
          "value_range": "0.10-0.50 linear — wide range driven by micro-roughness variation map"
        },
        "metallic": {
          "value": 1.0,
          "notes": "Fully metallic throughout. The apparent darkening of recesses is a roughness and geometry occlusion effect, not a dielectric coating. If a thin wax/soot darkening agent was applied historically, metallic can be masked to 0.85 in channel floors only."
        },
        "roughness": {
          "value_or_range": "0.15-0.65",
          "variation_map_needed": true,
          "notes": "Critical roughness variation map required. Crest high points: 0.10-0.18 (retains polish). Mid-relief transitions: 0.30-0.45. Engraved channel floors: 0.55-0.65 (tool-cut matte). This single roughness map drives all the apparent tonal contrast in the decorative field."
        },
        "normal_micro_surface": {
          "description": "Dense high-frequency normal map encoding all engraved line detail, acanthus leaf venation, rose petal micro-curvature, scrollwork profile cross-sections, and tool-mark striations in channel floors. This is the most complex normal map on the asset.",
          "intensity": "strong",
          "features": [
            "High-relief rose bloom petal layering and central spiral",
            "Acanthus leaf lobes with mid-rib and vein detail",
            "Scrollwork stem cross-section curvature",
            "Engraved channel V-profile walls",
            "Repoussé hammer dimple micro-texture on relief backs",
            "Graver tool striation marks along channel floors",
            "Beaded border rope detail"
          ]
        },
        "height_embossing": {
          "required": true,
          "description": "Medium-frequency height / displacement map required to capture the macro silhouette of the embossed roses and acanthus volumes that exceed normal map plausibility at close range. Displacement range approximately 0-8mm relative to base plate surface. Suitable for parallax occlusion mapping in game context or low-subdivision displacement in cinematics."
        },
        "surface_finish_treatment": "Repoussé embossing plus hand engraving (burin/graver), high points burnished back to bright polish after engraving, channel floors left in cut state with possible thin oil-soot blackening",
        "wear_aging_story": "Relief crests show the same minimal wear as mat_01. Channel floors show darkening consistent with either intentional antiquing or accumulated fine particulate. No rust breakthrough. Edges of deepest channels show the faintest cold-blue oxidation tint suggesting age but no active corrosion.",
        "reason_for_separation": "Despite sharing the same metallic substrate as mat_01, this zone requires a completely different and highly variable roughness map, a high-complexity normal map encoding all relief geometry, and a height map. Merging it with mat_01 would make roughness and normal map authoring impossible without masking — separation is the clean solution."
      },
      {
        "id": "mat_03",
        "name": "Wrapped Grip — Woven Textile or Cord",
        "material_class": "Fabric / Organic Fiber",
        "coverage_region": "Sword or dagger grip visible at lower-left of frame — the wrapped handle section",
        "physical_description": "Tightly wound cord or textile strip wrapped in a spiral pattern over an inner grip core. The material appears dark charcoal-grey to near-black, consistent with waxed linen cord, darkened leather strip, or wire wrap with age patina. The surface is matte with a fine woven or twisted fiber micro-texture.",
        "base_color_albedo": {
          "description": "Dark charcoal, near-black with very subtle warm undertone",
          "hex_approximation": "#2A2A28",
          "value_range": "0.03-0.07 linear"
        },
        "metallic": {
          "value": 0.0,
          "notes": "Fully dielectric. No metallic component. If wire wrap interpretation is correct, author as a separate thin metal element over this base — but visible evidence suggests fiber."
        },
        "roughness": {
          "value_or_range": "0.75-0.90",
          "variation_map_needed": false,
          "notes": "Consistently high roughness. Slight variation allowed at wrap crossing points where compression smooths the fiber."
        },
        "normal_micro_surface": {
          "description": "Tiled diagonal wrap normal map encoding the spiral cord ridge-and-valley profile plus individual fiber twist micro-detail.",
          "intensity": "moderate",
          "features": [
            "Spiral wrap ridge profile",
            "Cord twist micro-groove",
            "Fiber fray at wrap termination points",
            "Compression flat at crossing junctions"
          ]
        },
        "height_embossing": {
          "required": false,
          "description": "Normal map sufficient for game LOD. Parallax optional for hero close-up."
        },
        "surface_finish_treatment": "Waxed or oiled cord wrap — matte finish with possible light lacquer or grip wax for weather resistance",
        "wear_aging_story": "Visible use-wear: fibers slightly compressed and splayed at high-contact grip zones. Darkening consistent with hand oils and age. No fraying or breakage visible at this resolution.",
        "reason_for_separation": "Completely different material class (dielectric organic fiber) versus the metallic steel of mat_01 and mat_02. Metallic value is 0.0, roughness is 4-5x higher, and albedo is 10x darker. Cannot share any PBR channel with the steel materials."
      }
    ]
  }
}

