{
  "task": "Create a component deconstruction collage using only the top and bottom, extracting the visible upper and lower garments as isolated cutout pieces with exact material and construction fidelity.",
  "items": {
    "apparel": "Top: cropped motorcycle-style leather jacket isolated as a single clean cutout, featuring a saturated cobalt blue leather collar and sleeves, white front chest panels, black curved side insets, front silver zipper closure, two angled silver zip pockets, and black gothic-style FLORA and FAUNA text across the chest. Bottom: oversized black leather trousers isolated as a single separate cutout, ultra-wide and elongated with a glossy finish, high waist, front fly seam, and dramatic gathered pouch-like sculptural volume panels attached along the outer legs at thigh, calf, and ankle zones.",
    "headwear_and_neckwear": "None included in the collage. Exclude eyewear and bags from this category. No hat, scarf, or neckwear visible.",
    "hosiery_and_footwear": "Footwear should be excluded to respect the top-and-bottom-only crop logic. No visible hosiery should be extracted.",
    "accessories_and_jewelry": "Exclude accessories from the collage to follow the top-and-bottom-only directive. Do not include sunglasses, crossbody bag, gloves, chain detail, or handheld bags. No jewelry visible for extraction."
  },
  "layout_and_composition": {
    "background": "Pure clean white studio background, #FFFFFF, with no visible floor gradient, props, or environmental distractions.",
    "arrangement": "Arrange the jacket at the top center and the trousers directly below it, aligned vertically in a minimalist flat lay or floating cutout presentation. Preserve breathing room between both pieces so the silhouette and construction of each garment reads clearly. Keep the composition symmetrical and editorial, focused only on the upper and lower garment components.",
    "aesthetic": "minimalist luxury fashion deconstruction, top-and-bottom editorial flat lay"
  },
  "visual_fidelity": {
    "material_truth": "Maintain exact leather grain, gloss, seam placement, zipper hardware tone, panel color blocking, printed chest lettering, and the sculptural puffed construction of the trouser side volumes with 1:1 accuracy to the source image.",
    "lighting": "Apply even soft studio lighting across both isolated garments, matching the original clean fashion-shoot illumination while removing harsh cast shadows.",
    "quality": "Surgically clean cutout edges, ultra-sharp detail, no overlapping items, no mannequin body remnants, no distortion, and no added elements beyond the jacket and trousers."
  },
  "context": {
    "intent": "Focused fashion deconstruction of only the top and bottom garments for a clean component showcase.",
    "atmosphere": "clean, technical, elevated, and hyper-detailed"
  }
}

