      "shot_name": "Full Body Frontal",
      "framing": "Full Body Shot, head-to-toe.",
      "pose_description": "Frontal standing pose facing camera directly, arms relaxed naturally, wearing the blue cyber asymmetrical chic one-piece swimsuit exactly fitted to the body, barefoot with no shoes.",
      "background": "Solid Absolute White #FFFFFF"
    },
    "Panel_2": {
      "shot_name": "Full Body Back-to-Side",
      "framing": "Full Body Shot, head-to-toe.",
      "pose_description": "Model facing away from camera in a calm back-to-side stance, showing the back and shoulders of the asymmetrical swimsuit, head turned to look over shoulder or softly to the side, barefoot with no shoes.",
      "background": "Solid Absolute White #FFFFFF"
    },
    "Panel_3": {
      "shot_name": "Full Body 3/4 View",
      "framing": "Full Body Shot, head-to-toe.",
      "pose_description": "Natural three-quarter standing pose, elegant and simple, showcasing the cyber silhouette and asymmetrical cut of the blue one-piece swimsuit, barefoot with no shoes.",
      "background": "Solid Absolute White #FFFFFF"
    }
  },
  "background_specifications": {
    "color": "Absolute White #FFFFFF",
    "shadows": "Soft contact shadows on floor, grounded body placement, no floating.",
    "lighting": "Bright, uniform e-commerce studio lighting with subtle glossy highlights on skin and hair."
  },
  "model_specifications": {
    "consistency_lock": "CRITICAL: Maintain 100% absolute fidelity to the exact reference model across all three panels: young East Asian woman with fair luminous skin, slim elegant build, long straight glossy black hair, sharp center part, vivid electric-blue front hair panels framing the face, multiple silver metal snap hair clips arranged symmetrically around the hairline and sides, icy blue airbrushed cyber eye makeup extending across brows and upper face, dramatic oversized black spiked lashes, glossy black lower lash accents, small rhinestone clusters near the eyes, soft nude lips, refined facial structure, calm editorial expression, and identical beauty styling in every panel."
  },
  "garment_specifications": {
    "top": {
      "item_name": "Blue cyber asymmetrical chic one-piece swimsuit",
      "details": "One-piece swimsuit worn exactly as requested, sleek form-fitting sculptural fit, asymmetrical neckline and strap design, futuristic electric-blue tone with subtle technical sheen, clean high-fashion cyber styling, no extra layers."
    },
    "bottoms": {
      "item_name": "Integrated swimsuit bottom",
      "details": "Part of the same one-piece swimsuit, seamless matching blue cyber fabric, fitted and consistent across all panels."
